// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, spring, interpolate } from '../remotionShim';
// Google Fonts — module-level loadFont calls
import { makeLoadFont } from '../googleFonts';
const loadMontserrat = makeLoadFont('Montserrat');
const { fontFamily: montserratFamily } = loadMontserrat();



export type MomentumDictionaryProps = Record<string, any>;

const MomentumDictionary: React.FC<MomentumDictionaryProps> = ({
  backgroundColor = "#0a0a0a",
  transparentBackground = false,
  durationInSeconds = 12,
  word1 = "Momentum",
  word2 = "We need to go as fast as we possibly can",
  titleFontSize = 8,
  definitionFontSize = 3.5,
  primaryTextColor = "#ffffff",
  secondaryTextColor = "#cccccc",
  accentColor = "#ffffff",
  framesPerChar = 3,
  lineWidth = 100,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Logic to prevent parser errors
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Timings
  const word1Start = 15;
  const word1Duration = word1.length * framesPerChar;
  
  const holdFrames = 3 * fps; // 3 seconds hold based on 30fps standard
  const lineStart = word1Start + word1Duration + holdFrames;
  
  const word2Start = lineStart + 20;

  // Font sizing calculations based on width percentages
  const computedTitleSize = (width * titleFontSize) / 100;
  const computedDefSize = (width * definitionFontSize) / 100;

  // Word 1 (Title) Logic
  const w1Chars = Math.max(0, Math.floor((frame - word1Start) / framesPerChar));
  const w1Text = word1.slice(0, w1Chars);
  const w1IsTyping = frame >= word1Start && w1Chars < word1.length;
  const cursorBlink = Math.floor(frame / 15) % 2 === 0;
  
  // Title cursor disappears when the line animation begins
  const w1ShowCursor = frame >= word1Start && frame < lineStart && (w1IsTyping || cursorBlink);

  // Line Animation Logic
  const lineWidthProgress = spring({
    frame: frame - lineStart,
    fps,
    config: { damping: 200, mass: 0.5 },
  });
  
  const lineWidthPercent = interpolate(lineWidthProgress, [0, 1], [0, lineWidth], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // Word 2 (Definition) Logic
  const w2Chars = Math.max(0, Math.floor((frame - word2Start) / framesPerChar));
  const w2Text = word2.slice(0, w2Chars);
  const w2IsTyping = frame >= word2Start && w2Chars < word2.length;
  const w2ShowCursor = frame >= word2Start && (w2IsTyping || cursorBlink);

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        fontFamily: montserratFamily,
        justifyContent: "center",
        transition: "none",
      }}
    >
      <div
        style={{
          width: width * 0.7,
          marginLeft: width * 0.15,
          display: "flex",
          flexDirection: "column",
          alignItems: "flex-start",
          transition: "none",
        }}
      >
        {/* Word 1: Bold Title */}
        <h1
          style={{
            fontSize: computedTitleSize,
            fontWeight: 700,
            color: primaryTextColor,
            margin: 0,
            lineHeight: 1,
            transition: "none",
          }}
        >
          {w1Text}
          <span
            style={{
              display: "inline-block",
              width: width * 0.005,
              height: computedTitleSize * 0.875,
              backgroundColor: accentColor,
              marginLeft: width * 0.01,
              verticalAlign: "middle",
              opacity: w1ShowCursor ? 1 : 0,
              transition: "none",
            }}
          />
        </h1>

        {/* Separator Line */}
        <div
          style={{
            width: `${lineWidthPercent}%`,
            height: height * 0.004,
            backgroundColor: accentColor,
            marginTop: height * 0.04,
            marginBottom: height * 0.04,
            transformOrigin: "left center",
            transition: "none",
          }}
        />

        {/* Word 2: Dictionary Definition Style */}
        <div style={{ display: "flex", flexDirection: "column", transition: "none" }}>
          {frame >= word2Start && (
             <span
             style={{
               fontSize: computedDefSize * 0.57, // Proportionally scaled relative to definition size
               fontWeight: 400,
               color: secondaryTextColor,
               marginBottom: height * 0.01,
               fontStyle: "italic",
               opacity: spring({
                 frame: frame - word2Start,
                 fps,
                 config: { damping: 200 }
               }),
               transition: "none",
             }}
           >
             1. def
           </span>
          )}
         
          <p
            style={{
              fontSize: computedDefSize,
              fontWeight: 400,
              color: secondaryTextColor,
              margin: 0,
              lineHeight: 1.4,
              maxWidth: "100%",
              transition: "none",
            }}
          >
            {w2Text}
            <span
              style={{
                display: "inline-block",
                width: width * 0.003,
                height: computedDefSize,
                backgroundColor: accentColor,
                marginLeft: width * 0.005,
                verticalAlign: "middle",
                opacity: w2ShowCursor ? 1 : 0,
                transition: "none",
              }}
            />
          </p>
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default MomentumDictionary;